///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpgeneral/corpList.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_stdIndustry=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/corpList.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearchWithoutIndex();
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    await scwin.fnOrder("3", "D");
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchWithoutIndex
 * @description fn Search Without Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchWithoutIndex = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("beginIndex", "");
    scwin.fnClearBtnType();
    await scwin.fnInit();
};

/**
 * @method
 * @name fnClearBtnType
 * @description fn Clear Btn Type 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnClearBtnType = function () {
    $(document).find("a[id=btnType]").each(function() {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
    });
};

/**
 * @method
 * @name fnSetCorpName
 * @description fn Set Corp Name 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.fnSetCorpName = function (str) {
    $c.util.getComponent("dma_fnDownloadReq").set("comAbbrv", encodeURI(str));
};

/**
 * @method
 * @name fnClearCorpName
 * @description fn Clear Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnClearCorpName = function () {
    $c.util.getComponent("dma_fnDownloadReq").set("comAbbrv", "");
    $c.util.getComponent('AKCKwd').setValue("");
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.fnSetCorpName($c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchCorpList");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} ipt_comAbbrv ipt_comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + ipt_comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(ipt_comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
};

/**
 * @method
 * @name fnBtnType
 * @description fn Btn Type 처리
 * @param {*} type type
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnBtnType = async function (type, idx) {
    scwin.fnClearBtnType();
    scwin.fnClearCorpName();
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("beginIndex", type);
    $(document).find("a[id=btnType]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            }
    });
    await scwin.fnInit();
};
